package com.coraline.secrets;
import com.coraline.feast.*;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraft.world.item.*;
import java.util.*;

@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class SecretDialogueGameTests {
    @GameTest(template="empty") public static void rewardPickerResumesWithoutReroll(GameTestHelper h){var p=SecretsGameTests.fixture(h);var s=SecretTransactions.state(p);s.journal.add("house_codes");SecretTransactions.makeBlackmail(p,List.of("house_codes"));SecretTransactions.offer(p,p.getInventory().getItem(0),1);h.assertFalse(SecretTransactions.resumeReward(p),"Undecided offer opened picker");SecretsGameTests.finishOffer(p);var before=s.save();h.assertTrue(SecretTransactions.resumeReward(p),"Accepted picker could not reopen");h.assertTrue(before.equals(s.save()),"Reopening changed transaction");SecretTransactions.reward(p,0);h.assertFalse(SecretTransactions.resumeReward(p),"Committed picker reopened");h.succeed();}
    @GameTest(template="empty") public static void completionAckCannotSkipDuration(GameTestHelper h){var p=SecretsGameTests.fixture(h);var s=SecretTransactions.state(p);s.journal.add("house_codes");SecretTransactions.makeBlackmail(p,List.of("house_codes"));SecretTransactions.offer(p,p.getInventory().getItem(0),1);var n=s.dialogue;String sound=n.getString("Queue");n.remove("Queue");n.putString("Playing",sound);n.putBoolean("OfferSpoken",true);n.putLong("Until",OtherMotherLoop.now(p)+20);SecretDialogue.finished(p,"wrong_sound");h.assertFalse(n.getBoolean("Finished"),"Wrong audio acknowledged");SecretDialogue.finished(p,sound);SecretTransactions.resolveOffer(p);h.assertTrue(s.pendingReward==-1,"Client skipped duration");n.putLong("Until",OtherMotherLoop.now(p));SecretTransactions.resolveOffer(p);h.assertTrue(s.pendingReward>=0,"Finished offer not resolved");h.succeed();}
    @GameTest(template="empty") public static void noInventoryInspectionThroughWalls(GameTestHelper h){var p=SecretsGameTests.fixture(h);SecretsGameTests.warm(p);h.runAfterDelay(20,()->{var at=p.blockPosition();var m=com.coraline.registry.ModEntities.MOM.get().create(p.serverLevel());m.makeOtherParent(0);m.setNoAi(true);m.setPos(p.getX()+3,p.getY(),p.getZ());p.serverLevel().addFreshEntity(m);OtherMotherLoop.scene(p).mom=m.getUUID();h.assertTrue(MotherSearch.mother(p)==m,"Missing mother fixture");for(int z=-2;z<=2;z++)for(int y=0;y<4;y++)p.serverLevel().setBlock(at.offset(1,y,z),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),2);SecretTransactions.issue(p,"soulglass");MotherSearch.catchPlayer(p);h.assertTrue(SecretTransactions.state(p).exposed.isEmpty(),"Mother inspected through wall");for(int z=-2;z<=2;z++)for(int y=0;y<4;y++)p.serverLevel().setBlock(at.offset(1,y,z),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),2);MotherSearch.catchPlayer(p);var s=SecretTransactions.state(p);h.assertTrue(s.exposed.contains("soulglass")&&s.dialogue.getString("Queue").contains("secrets_item"),"Visible inspection did not choose item dialogue");float suspicion=OtherMotherLoop.scene(p).loop.suspicion;MotherSearch.catchPlayer(p);h.assertTrue(suspicion==OtherMotherLoop.scene(p).loop.suspicion,"Repeated catch penalty");Reconciliation.cancel(p);s.dialogue.remove("Queue");s.world.putLong("CatchUntil",0);MotherSearch.catchPlayer(p);h.assertTrue(suspicion==OtherMotherLoop.scene(p).loop.suspicion,"Same encounter repeated after cooldown");m.setPos(p.getX()+20,p.getY(),p.getZ());for(int i=0;i<60;i++)MotherSearch.tick(p);m.setPos(p.getX()+3,p.getY(),p.getZ());MotherSearch.catchPlayer(p);h.assertTrue(OtherMotherLoop.scene(p).loop.suspicion>suspicion,"New separated encounter never detected");SecretsGameTests.cool(p);h.succeed();});}
    public static final class RejectDrops {
        @net.minecraftforge.eventbus.api.SubscribeEvent public void join(net.minecraftforge.event.entity.EntityJoinLevelEvent e){if(e.getEntity() instanceof net.minecraft.world.entity.item.ItemEntity item&&item.getItem().getTag()!=null&&item.getItem().getTag().hasUUID("SecretReceipt"))e.setCanceled(true);}
    }
    @GameTest(template="empty") public static void deliveryFailureRetainsOfferAndChoice(GameTestHelper h){var p=SecretsGameTests.fixture(h);var s=SecretTransactions.state(p);s.journal.add("soulglass");SecretTransactions.makeBlackmail(p,List.of("soulglass"));var mail=p.getInventory().getItem(0);SecretTransactions.offer(p,mail,1);SecretsGameTests.finishOffer(p);for(int i=1;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));float trust=OtherMotherLoop.scene(p).loop.trust;var blocker=new RejectDrops();net.minecraftforge.common.MinecraftForge.EVENT_BUS.register(blocker);try{SecretTransactions.reward(p,1);}finally{net.minecraftforge.common.MinecraftForge.EVENT_BUS.unregister(blocker);}h.assertTrue(s.pendingReward>=0&&!mail.isEmpty()&&s.dialogue.getString("Queue").isEmpty(),"Failed delivery committed acceptance");h.assertTrue(trust==OtherMotherLoop.scene(p).loop.trust,"Penalty before delivery");p.getInventory().setItem(1,ItemStack.EMPTY);SecretTransactions.reward(p,0);h.assertTrue(p.getInventory().countItem(Items.DIAMOND)>0&&p.getInventory().countItem(Items.EMERALD)==0,"Retry changed selected reward");h.assertTrue(s.pendingReward==-1&&mail.isEmpty()&&s.dialogue.getString("Queue").contains("accept"),"Recovery did not finish");h.succeed();}
    @GameTest(template="empty") public static void exactlySixtyRegisteredVariations(GameTestHelper h){var ids=new HashSet<String>();for(var pool:SecretDialogue.pools()){h.assertTrue(pool.size()==2,"Not two variations");for(int i=0;i<2;i++){String name=pool.sound(i);h.assertTrue(ids.add(name)&&VisitAudio.SOUNDS.containsKey(name),"Missing/duplicate sound registration");for(int trial=0;trial<20;trial++)h.assertTrue(!OtherMotherDialogue.choose(pool,name,net.minecraft.util.RandomSource.create(trial)).equals(name),"Immediate repeat");}}h.assertTrue(ids.size()==60,"Not sixty voices");h.succeed();}
    @GameTest(template="empty") public static void priorityAndClassifierAreShared(GameTestHelper h){h.assertTrue(SecretDialogue.caught(true,true)==SecretDialogue.Event.SECRET_AREA_CAUGHT,"Area priority");h.assertTrue(SecretDialogue.caught(false,true)==SecretDialogue.Event.SECRET_AREA_CAUGHT,"Secret priority");h.assertTrue(SecretDialogue.caught(false,false)==SecretDialogue.Event.ORDINARY_AREA_CAUGHT,"Ordinary fallback");var p=SecretsGameTests.fixture(h);for(float trust:new float[]{0,.2F,.5F,.8F,1})for(float suspicion:new float[]{0,.2F,.5F,.8F,1}){OtherMotherLoop.relationship(p,trust,suspicion);h.assertTrue(SecretDialogue.state(p)==OtherMotherLoopState.classify(trust,suspicion),"Classifier forked");}h.succeed();}
    @GameTest(template="empty") public static void offerWaitsAndCapturesState(GameTestHelper h){var p=SecretsGameTests.fixture(h);OtherMotherLoop.relationship(p,.8F,.1F);var s=SecretTransactions.state(p);s.journal.add("soul_prisons");SecretTransactions.makeBlackmail(p,List.of("soul_prisons"));var item=p.getInventory().items.stream().filter(i->i.is(SecretsItems.BLACKMAIL.get())).findFirst().orElseThrow();h.assertTrue(SecretTransactions.offer(p,item,1),"Offer refused");var initial=s.save();h.assertFalse(SecretTransactions.offer(p,item,0),"Spam restarted offer");SecretTransactions.resolveOffer(p);h.assertTrue(s.pendingReward==-1&&s.exposed.isEmpty()&&!item.isEmpty(),"Premature resolution");h.assertTrue(s.save().equals(initial),"Spam or early resolve mutated ledger");OtherMotherLoop.scene(p).loop.secrets=SecretsState.load(s.save());s=SecretTransactions.state(p);SecretsGameTests.finishOffer(p);h.assertTrue(s.pendingReward==3,"Accepted reward missing");h.assertTrue(!item.isEmpty(),"Consumed before payout");OtherMotherLoop.relationship(p,.1F,.9F);SecretTransactions.reward(p,0);h.assertTrue(s.dialogue.getString("Queue").contains("accept_high_low"),"State changed mid encounter");h.assertTrue(p.getInventory().countItem(Items.EMERALD)>0&&item.isEmpty(),"Delivery/consumption failed");h.succeed();}
    @GameTest(template="empty") public static void withdrawalDoesNotConsumeOrPenalize(GameTestHelper h){var p=SecretsGameTests.fixture(h);var s=SecretTransactions.state(p);s.journal.add("house_codes");SecretTransactions.makeBlackmail(p,List.of("house_codes"));var item=p.getInventory().items.stream().filter(i->i.is(SecretsItems.BLACKMAIL.get())).findFirst().orElseThrow();SecretTransactions.offer(p,item,0);p.getInventory().clearContent();SecretsGameTests.finishOffer(p);h.assertTrue(s.blackmail.size()==1&&s.exposed.isEmpty()&&OtherMotherLoop.scene(p).loop.suspicion==0,"Withdrawn offer penalized");h.assertFalse(s.dialogue.hasUUID("Offer"),"Withdrawn offer locked forever");h.succeed();}
    @GameTest(template="empty") public static void rejectionHasOnePenaltyAndNoLoot(GameTestHelper h){var p=SecretsGameTests.fixture(h);OtherMotherLoop.relationship(p,.5F,.3F);var s=SecretTransactions.state(p);s.journal.add("soulglass");SecretTransactions.makeBlackmail(p,List.of("soulglass"));var item=p.getInventory().items.stream().filter(i->i.is(SecretsItems.BLACKMAIL.get())).findFirst().orElseThrow();SecretTransactions.offer(p,item,0);SecretsGameTests.finishOffer(p);float suspicion=OtherMotherLoop.scene(p).loop.suspicion;SecretTransactions.resolveOffer(p);SecretTransactions.reward(p,0);h.assertTrue(suspicion==OtherMotherLoop.scene(p).loop.suspicion&&suspicion>.3F,"Duplicated/missing rejection penalty");h.assertTrue(s.pendingReward==-1&&p.getInventory().countItem(Items.EMERALD)==0&&s.exposed.contains("soulglass")&&item.isEmpty(),"Rejected payout or missing exposure");h.assertTrue(s.dialogue.getString("Queue").contains("reject"),"Wrong response");h.succeed();}
    @GameTest(template="empty") public static void previewCannotAlterOtherOwner(GameTestHelper h){var a=SecretsGameTests.fixture(h);var b=SecretsGameTests.fixture(h);var before=OtherMotherLoop.scene(b).loop.save();SecretDialogue.preview(a,0,0,0);h.assertTrue(SecretTransactions.state(a).dialogue.isEmpty(),"Nonoperator preview accepted");h.assertTrue(OtherMotherLoop.scene(b).loop.save().equals(before),"Other owner changed");h.succeed();}
}
